def make_item(grammar, meaning, usage, examples, mistakes, compare=None, level=None):
    return {
        "grammar": grammar,
        "meaning": meaning,
        "usage": usage,
        "examples": examples,
        "mistakes": mistakes,
        "compare": compare or "",
        "id": str(uuid.uuid4()),
        "level": level
    }

