# 生成并写入
def build(level, items):
    out = [make_item(*x, level=level) for x in items]
    path = os.path.join(OUT_DIR, f'{level}_grammar.json')
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    return len(out)

counts = {
    'A1': build('A1', A1),
    'A2': build('A2', A2),
    'B1': build('B1', B1),
    'B2': build('B2', B2),
    'C1': build('C1', C1),
}

summary = {
    'A1_words': 1076, 'A1_grammar': counts['A1'],
    'A2_words': 990, 'A2_grammar': counts['A2'],
    'B1_words': 902, 'B1_grammar': counts['B1'],
    'B2_words': 1571, 'B2_grammar': counts['B2'],
    'C1_words': 1404, 'C1_grammar': counts['C1'],
}
with open(os.path.join(OUT_DIR, 'summary.json'), 'w', encoding='utf-8') as f:
    json.dump(summary, f, ensure_ascii=False, indent=2)

print(counts)
print(summary)
